import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.lang.management.ManagementFactory;
import java.lang.management.ThreadMXBean;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicLong;

public final class SearchServer {
    private static final ThreadMXBean THREADS = ManagementFactory.getThreadMXBean();
    private static final AtomicLong REQUESTS = new AtomicLong();
    private static volatile long sink;

    private SearchServer() {}

    private static void burnCpuMicros(long microseconds) {
        long started = THREADS.getCurrentThreadCpuTime();
        long target = microseconds * 1_000L;
        long value = sink + 1;
        while (THREADS.getCurrentThreadCpuTime() - started < target) {
            value = (value * 2862933555777941757L) + 3037000493L;
            value ^= value >>> 17;
        }
        sink = value;
    }

    private static void reply(HttpExchange exchange, int status, String body)
            throws IOException {
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        exchange.getResponseHeaders().set("Content-Type", "application/json");
        exchange.getResponseHeaders().set("Cache-Control", "no-store");
        exchange.sendResponseHeaders(status, bytes.length);
        exchange.getResponseBody().write(bytes);
        exchange.close();
    }

    private static void search(HttpExchange exchange) throws IOException {
        burnCpuMicros(250);
        reply(exchange, 200, "{\"ok\":true,\"request\":"
                + REQUESTS.incrementAndGet() + "}\n");
    }

    private static void health(HttpExchange exchange) throws IOException {
        // Intentionally non-trivial: under the injected 100m cap this probe
        // competes with request work and exceeds its one-second timeout.
        burnCpuMicros(50_000);
        reply(exchange, 200, "{\"ok\":true}\n");
    }

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 128);
        server.createContext("/search", SearchServer::search);
        server.createContext("/healthz", SearchServer::health);
        server.setExecutor(Executors.newFixedThreadPool(64));
        server.start();
        System.out.println("search-api listening on :8080");
    }
}
